votes.sql:
WITH card_counts AS (
    SELECT name,
           (LENGTH(printings) - LENGTH(REPLACE(printings, ',', '')) + 1) AS printing_count
    FROM cards
    WHERE setCode = '10E'
)
SELECT name
FROM card_counts
WHERE printing_count = (SELECT MAX(printing_count) FROM card_counts);
}

